def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the largest 4-connected nonzero component: the filled board.
    seen = set()
    best = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(comp) > len(best):
                best = comp

    r0 = min(r for r, c in best)
    r1 = max(r for r, c in best)
    c0 = min(c for r, c in best)
    c1 = max(c for r, c in best)
    board = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(board), len(board[0])
    inside = {(r, c) for r in range(r0, r1 + 1)
              for c in range(c0, c1 + 1)}

    counts = {}
    positions = {}
    for r in range(H):
        for c in range(W):
            v = board[r][c]
            if v != 1:
                counts[v] = counts.get(v, 0) + 1
                positions[v] = (r, c)

    # Singleton colors inside the board are positioned by matching outside dots.
    markers = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and (r, c) not in inside and counts.get(v) == 1:
                markers[v] = (r, c)

    if not markers:
        return board

    rr = [p[0] for p in markers.values()]
    cc = [p[1] for p in markers.values()]
    rmin, rmax = min(rr), max(rr)
    cmin, cmax = min(cc), max(cc)

    def corner(r, c, height, width):
        return ("T" if r < height / 2 else "B",
                "L" if c < width / 2 else "R")

    targets = {
        color: corner(r - rmin, c - cmin, rmax - rmin + 1, cmax - cmin + 1)
        for color, (r, c) in markers.items()
    }

    transforms = [
        (H, W, lambda r, c: (r, c)),
        (H, W, lambda r, c: (H - 1 - r, c)),
        (H, W, lambda r, c: (r, W - 1 - c)),
        (H, W, lambda r, c: (H - 1 - r, W - 1 - c)),
        (W, H, lambda r, c: (c, r)),
        (W, H, lambda r, c: (W - 1 - c, H - 1 - r)),
        (W, H, lambda r, c: (c, H - 1 - r)),
        (W, H, lambda r, c: (W - 1 - c, r)),
    ]

    best_transform = transforms[0]
    best_score = float("inf")
    for out_h, out_w, mapping in transforms:
        score = 0
        for color, (r, c) in positions.items():
            if color not in targets:
                continue
            nr, nc = mapping(r, c)
            if corner(nr, nc, out_h, out_w) != targets[color]:
                score += 1
        if score < best_score:
            best_score = score
            best_transform = (out_h, out_w, mapping)

    out_h, out_w, mapping = best_transform
    result = [[0] * out_w for _ in range(out_h)]
    for r in range(H):
        for c in range(W):
            nr, nc = mapping(r, c)
            result[nr][nc] = board[r][c]
    return result
